DESIGNS=[]
def E(de,en,ode,oen):return dict(essentialUnderstandingDe=de,essentialUnderstandingEn=en,observablePerformanceDe=ode,observablePerformanceEn=oen)
def R(id,tde,ten,cde,cen,basis='written-explicit-task'):return dict(expectationId=id,taskClauseDe=tde,taskClauseEn=ten,criterionDe=cde,criterionEn=cen,creditBasis=basis)
def C(title,dde,den,rows,mde,men,**kw):return dict(title=title,dataDe=dde,dataEn=den,taskRows=rows,modelAnswerDe=mde,modelAnswerEn=men,**kw)
